static int cpy_omf_names(r_bin_omf_obj *obj) {
    OMF_record_handler *tmp = obj->records;
    OMF_multi_datas *lname;
    int ct_obj = 0;
    int ct_rec;

    while ((tmp = get_next_omf_record_type(tmp, OMF_LNAMES))) {
